interface TechIconProps {
  name: string;
  className?: string;
}

export function TechIcon({ name, className }: TechIconProps) {
  const brand = BRAND_VECTORS[name];

  if (brand) {
    return (
      <svg
        viewBox="0 0 24 24"
        aria-hidden="true"
        className={cn(
          'h-4 w-4 shrink-0',
          brand.adaptiveMono && 'text-ink',
          className
        )}
        style={brand.color ? { color: brand.color } : undefined}
        fill="currentColor"
      >
        <path d={brand.path} />
      </svg>
    );
  }

  const lower = name.toLowerCase();
  if (lower.includes('prompt')) {
    return <Sparkles aria-hidden="true" className={cn('h-4 w-4 shrink-0 text-amber-400', className)} />;
  }
  if (lower.includes('ai') || lower.includes('llm')) {
    return <Bot aria-hidden="true" className={cn('h-4 w-4 shrink-0 text-emerald-400', className)} />;
  }
  if (lower.includes('rest') || lower.includes('api')) {
    return <Globe aria-hidden="true" className={cn('h-4 w-4 shrink-0 text-sky-400', className)} />;
  }
  if (lower.includes('test')) {
    return <CheckCircle2 aria-hidden="true" className={cn('h-4 w-4 shrink-0 text-emerald-400', className)} />;
  }

  return <Code2 aria-hidden="true" className={cn('h-4 w-4 shrink-0 text-ink-muted', className)} />;
}
